/* eslint-disable no-restricted-syntax, no-invalid-this */

'use strict';

// MODULES //

var setReadWrite = require( '@stdlib/utils/define-nonenumerable-read-write-accessor' );
var setReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var setReadOnlyAccessor = require( '@stdlib/utils/define-nonenumerable-read-only-accessor' );
var config = require( './../config.js' );
var log = require( './../log.js' );
var getRaw = require( './raw/get.js' );
var setRaw = require( './raw/set.js' );
var getTransformed = require( './transformed/get.js' );


// FUNCTIONS //

/**
* Callback invoked upon receiving an HTTP response.
*
* @private
* @param {Response} response - response object
* @returns {Promise} promise which resolves upon converting response content to JSON
*/
function onResponse( response ) {
	return response.json();
}


// MAIN //

/**
* Constructor for a visualization schema manager.
*
* @private
* @constructor
* @param {Object} state - state object
* @returns {Schema} schema manager instance
*/
function Schema( state ) {
	if ( !( this instanceof Schema ) ) {
		return new Schema( state );
	}
	this._state = state;
	this._raw = null;
	this._transformed = null;
	return this;
}

/**
* Raw visualization schema.
*
* @name raw
* @memberof Schema.prototype
* @type {Object}
*/
setReadWrite( Schema.prototype, 'raw', getRaw, setRaw );

/**
* Resolves a visualization schema.
*
* @name resolve
* @memberof Schema.prototype
* @type {Function}
* @param {Callback} [clbk] - callback to invoke upon completion
*/
setReadOnly( Schema.prototype, 'resolve', function resolve( clbk ) {
	var self = this;

	log( 'Resolving schema...' );
	fetch( config.routes.schema )
		.then( onResponse )
		.then( onJSON )
		.catch( onError );

	/**
	* Callback invoked upon resolving a schema.
	*
	* @private
	* @param {Object} schema - schema
	* @returns {void}
	*/
	function onJSON( schema ) {
		log( 'Successfully resolved schema.' );
		self.raw = schema;
		if ( clbk ) {
			return clbk();
		}
	}

	/**
	* Callback invoked upon encountering an error.
	*
	* @private
	* @param {Error} error - error object
	* @returns {void}
	*/
	function onError( error ) {
		console.error( 'Encountered an error when attempting to resolve a schema. Error: %s', error.message );
		if ( clbk ) {
			return clbk( error );
		}
	}
});

/**
* Transformed visualization schema.
*
* @name transformed
* @memberof Schema.prototype
* @type {Object}
*/
setReadOnlyAccessor( Schema.prototype, 'transformed', getTransformed );


// EXPORTS //

module.exports = Schema;
